/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: installAudiovisualStream, observeContinuity, gateOriginalStream, expectAudioSignal,
 *              expectNoPreviewActivity
 *   Constants: otherPreview
 *   Variables: audiovisualVideo, dedicatedVideo
 * Tests
 *   - the device default starts an audible original-stream hover after a real page gesture
 *   - a cross-tab default change preserves the current preview and mutes the next automatic preview
 *   - a rejected automatic sound attempt keeps the same preview moving muted until manual unmute
 *   - native browser autoplay policy
 *     - a fresh page reports its actual browser autoplay result and still supports manual sound
 *   - automatic hover never interrupts an already playing shared source or adds overlapping audio
 *   - a cold first click auditions decoded audio without warming a hover preview or the shared player
 *   - unmuting a running original-stream hover keeps its native clock, frames and media lifecycle
 *   - a pending original-stream audition keeps the dedicated clip moving until decoded handoff
 *   - cancelling an audition while its original stream is pending releases both same-card elements
 *   - configured muted hover stays silent while keyboard auditions retain audio, their stream and one-preview ownership
 *   - audible preview pauses the shared source without changing its elapsed time or album queue
 *   - touch audio preview
 *     - a tap unmutes real audio and a second tap mutes the same continuing stream
 * @end-catalog */

import type { Locator, Page } from '@playwright/test';
import { execFileSync } from 'node:child_process';

import { catalogIds, trackFixtures } from './fixtures/catalog';
import { fulfillMedia, type BrowserApiFixture } from './support/apiRoutes';
import { expect, test } from './support/test';

// Trace snapshots mark a CDP user gesture and would invalidate the fresh-page autoplay observation.
test.use({ trace: 'off' });

let audiovisualVideo: Buffer;
let dedicatedVideo: Buffer;
const otherPreview = { ...trackFixtures[0], id: 'e2e-other-preview', title: 'Another Light',
  streamUrl: '/content/mediaTrack/stream/e2e-other-preview' };

test.beforeAll(() => {
  // The ordinary catalog Video fixture is silent. Generate real Opus audio without a binary asset.
  audiovisualVideo = execFileSync('ffmpeg', ['-v', 'error',
    '-f', 'lavfi', '-i', 'testsrc2=size=64x36:rate=24:duration=15',
    '-f', 'lavfi', '-i', 'sine=frequency=440:sample_rate=48000:duration=15',
    '-map', '0:v', '-map', '1:a', '-c:v', 'libvpx', '-threads', '1', '-b:v', '16k',
    '-c:a', 'libopus', '-b:a', '12k', '-t', '15', '-f', 'webm', 'pipe:1'],
  { maxBuffer: 1024 * 1024 });
  dedicatedVideo = execFileSync('ffmpeg', ['-v', 'error', '-i', 'pipe:0', '-map', '0:v:0',
    '-an', '-c:v', 'copy', '-t', '6.4', '-f', 'webm', 'pipe:1'],
  { input: audiovisualVideo, maxBuffer: 1024 * 1024 });
});

/** Keeps the silent dedicated clip enabled, so explicit auditions must deliberately choose the stream. */
const installAudiovisualStream = async (page: Page, { twoCards = false, motionPreviews = true } = {}) => {
  await page.route('**/api/listener/v1/presentation-capabilities', route => route.fulfill({
    json: { contractVersion: 1, motionPreviews }
  }));
  await page.route(`**/content/mediaTrack/motion-preview/${catalogIds.firstTrack}`, route =>
    fulfillMedia(route, dedicatedVideo, 'video/webm'));
  await page.route('**/content/mediaTrack/stream/*', route => {
    const path = new URL(route.request().url()).pathname;
    return [catalogIds.firstTrack, otherPreview.id].some(id => path.endsWith(`/${id}`))
      ? fulfillMedia(route, audiovisualVideo, 'video/webm') : route.fallback();
  });
  if (twoCards) await page.route('**/api/listener/v1/videos?**', route => route.fulfill({
    json: { items: [trackFixtures[0], otherPreview], nextCursor: null }
  }));
};

/** Records native media work without replacing decoding, the media clock, or frame presentation. */
const observeContinuity = async (preview: Locator) => {
  const media = await preview.elementHandle();
  const probe = await media!.evaluateHandle(element => {
    const video = element as HTMLVideoElement;
    const counts = { play: 0, pause: 0, load: 0, loadstart: 0, loadedmetadata: 0, emptied: 0,
      seeking: 0, seeked: 0 };
    const nativePlay = video.play.bind(video);
    const nativePause = video.pause.bind(video);
    const nativeLoad = video.load.bind(video);
    video.play = () => { counts.play++; return nativePlay(); };
    video.pause = () => { counts.pause++; nativePause(); };
    video.load = () => { counts.load++; nativeLoad(); };
    for (const event of ['loadstart', 'loadedmetadata', 'emptied', 'seeking', 'seeked'] as const) {
      video.addEventListener(event, () => { counts[event]++; });
    }
    let frames = 0;
    let presentedFrames = 0;
    let mediaTime = 0;
    let audibleFrames: number | null = null;
    video.addEventListener('volumechange', () => { if (!video.muted) audibleFrames = frames; });
    const sampleFrame: VideoFrameRequestCallback = (_time, metadata) => {
      frames++;
      presentedFrames = metadata.presentedFrames;
      mediaTime = metadata.mediaTime;
      if (video.isConnected) video.requestVideoFrameCallback(sampleFrame);
    };
    video.requestVideoFrameCallback(sampleFrame);
    return { read: () => ({ counts: { ...counts }, frames, presentedFrames, mediaTime, audibleFrames,
      currentTime: video.currentTime, connected: video.isConnected, muted: video.muted,
      paused: video.paused, source: video.src, opacity: Number(getComputedStyle(video).opacity) }) };
  });
  return { media: media!, read: () => probe.evaluate(value => value.read()) };
};

/** Holds original-stream bytes until the test deliberately releases the pending audition. */
const gateOriginalStream = async (page: Page) => {
  let release!: () => void;
  let complete!: () => void;
  let requested = false;
  let failure: unknown;
  const gate = new Promise<void>(resolve => { release = resolve; });
  const completed = new Promise<void>(resolve => { complete = resolve; });
  page.once('close', release);
  await page.route(`**/content/mediaTrack/stream/${catalogIds.firstTrack}`, async route => {
    requested = true;
    await gate;
    try { await fulfillMedia(route, audiovisualVideo, 'video/webm'); }
    catch (error) { failure = error; }
    finally { complete(); }
  });
  return { requested: () => requested, release: async () => {
    release();
    await completed;
    if (failure) throw failure;
  } };
};

/** Proves decoded, nonzero audio rather than trusting a false muted flag on a silent Video. */
const expectAudioSignal = async (preview: Locator) => {
  const signal = await preview.evaluate(async element => {
    const video = element as HTMLVideoElement;
    const context = new AudioContext();
    const analyser = context.createAnalyser();
    const source = context.createMediaElementSource(video);
    source.connect(analyser);
    analyser.connect(context.destination);
    await context.resume();
    const samples = new Float32Array(analyser.fftSize);
    let peak = 0;
    const deadline = performance.now() + 2_000;
    while (peak < 0.005 && performance.now() < deadline) {
      analyser.getFloatTimeDomainData(samples);
      for (const sample of samples) peak = Math.max(peak, Math.abs(sample));
      await new Promise<void>(resolve => requestAnimationFrame(() => resolve()));
    }
    const result = { peak, muted: video.muted, paused: video.paused, readyState: video.readyState };
    // This is the last media assertion before stopping the preview; closing removes the test audio graph.
    source.disconnect();
    await context.close();
    return result;
  });
  expect(signal).toMatchObject({ muted: false, paused: false });
  expect(signal.readyState).toBeGreaterThanOrEqual(2);
  expect(signal.peak).toBeGreaterThan(0.005);
};

const expectNoPreviewActivity = (api: BrowserApiFixture) => {
  expect(api.calls.filter(call => call.pathname.includes('recently-played')
    || call.pathname.startsWith('/api/social/') && call.method !== 'GET')).toEqual([]);
};

test('the device default starts an audible original-stream hover after a real page gesture', async ({ api, page }) => {
  await installAudiovisualStream(page);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude/videos');
  expect(await page.evaluate(() => localStorage.getItem('finitude:video-preview-muted'))).toBeNull();
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  await card.hover();
  const preview = card.locator('video[data-video-preview]');
  await expect(preview).toHaveAttribute('data-ready', 'true');
  expect(await preview.evaluate(element => ({ muted: (element as HTMLVideoElement).muted,
    source: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ muted: false,
    source: `/content/mediaTrack/stream/${catalogIds.firstTrack}` });
  await expect(card.getByRole('button', { name: 'Mute preview for First Light', exact: true }))
    .toHaveAttribute('aria-pressed', 'true');
  await expect(page.getByRole('region', { name: 'Now playing', exact: true }).getByText('Nothing playing')).toBeVisible();
  await expectAudioSignal(preview);
  await page.keyboard.press('Escape');
  await expect(preview).toHaveCount(0);
  expectNoPreviewActivity(api);
});

test('a cross-tab default change preserves the current preview and mutes the next automatic preview', async ({ api, page }) => {
  await installAudiovisualStream(page);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude/videos');
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  const preview = card.locator('video[data-video-preview]');
  await card.hover();
  await expect(preview).toHaveAttribute('data-ready', 'true');
  const continuity = await observeContinuity(preview);
  await expect.poll(async () => (await continuity.read()).frames).toBeGreaterThan(0);
  const before = await continuity.read();
  expect(before).toMatchObject({ muted: false, paused: false });
  await page.evaluate(() => {
    const key = 'finitude:video-preview-muted';
    localStorage.setItem(key, 'true');
    window.dispatchEvent(new StorageEvent('storage', { key, newValue: 'true', storageArea: localStorage }));
  });
  await expect.poll(async () => (await continuity.read()).currentTime).toBeGreaterThan(before.currentTime + 0.15);
  expect(await continuity.read()).toMatchObject({ connected: true, muted: false, paused: false,
    source: before.source, counts: before.counts });
  await expect(preview).toHaveCount(1);
  await expect(card.getByRole('button', { name: 'Mute preview for First Light', exact: true }))
    .toHaveAttribute('aria-pressed', 'true');

  await page.mouse.move(0, 0);
  await expect(preview).toHaveCount(0);
  const settings = page.getByRole('button', { name: 'Preview settings', exact: true });
  await settings.click();
  const preferences = page.getByRole('dialog', { name: 'Preview settings', exact: true });
  await expect(preferences.getByRole('checkbox', { name: 'Mute previews by default', exact: true })).toBeChecked();
  await preferences.getByRole('button', { name: 'Close', exact: true }).click();
  await card.hover();
  await expect(preview).toHaveAttribute('data-ready', 'true');
  expect(await preview.evaluate(element => ({ muted: (element as HTMLVideoElement).muted,
    source: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ muted: true,
    source: `/content/mediaTrack/motion-preview/${catalogIds.firstTrack}` });
  expect((await continuity.read()).connected).toBe(false);
  await expect(page.getByRole('region', { name: 'Now playing', exact: true }).getByText('Nothing playing')).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(preview).toHaveCount(0);
  expectNoPreviewActivity(api);
});

test('a rejected automatic sound attempt keeps the same preview moving muted until manual unmute', async ({ api, page }) => {
  await installAudiovisualStream(page);
  await page.addInitScript(() => {
    localStorage.setItem('finitude:video-browse-view', 'immersive');
    const nativePlay = HTMLMediaElement.prototype.play;
    let rejected = false;
    HTMLMediaElement.prototype.play = function play(this: HTMLMediaElement) {
      if (this.hasAttribute('data-video-preview') && !this.muted && !rejected) {
        rejected = true;
        this.setAttribute('data-e2e-autoplay-rejected', 'true');
        return Promise.reject(new DOMException('Controlled automatic audio policy refusal.', 'NotAllowedError'));
      }
      return nativePlay.call(this);
    };
  });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude/videos');
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  await card.hover();
  const preview = card.locator('video[data-video-preview]');
  await expect(preview).toHaveAttribute('data-e2e-autoplay-rejected', 'true');
  await expect(preview).toHaveAttribute('data-ready', 'true');
  await expect(card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }))
    .toHaveAttribute('aria-pressed', 'false');
  const continuity = await observeContinuity(preview);
  const before = await continuity.read();
  expect(before).toMatchObject({ muted: true, paused: false });
  await expect.poll(async () => (await continuity.read()).currentTime).toBeGreaterThan(before.currentTime + 0.2);
  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).click();
  await expect.poll(async () => (await continuity.read()).muted).toBe(false);
  expect(await continuity.read()).toMatchObject({ connected: true, paused: false, source: before.source, counts: before.counts });
  await expect(preview).toHaveCount(1);
  await expectAudioSignal(preview);
  await page.keyboard.press('Escape');
  await expect(preview).toHaveCount(0);
  expectNoPreviewActivity(api);
});

test.describe('native browser autoplay policy', () => {
  test('a fresh page reports its actual browser autoplay result and still supports manual sound', async ({ api, page }) => {
    await installAudiovisualStream(page);
    type PolicyObservation = { automaticMuted: boolean; userActivation: boolean;
      attempts: Array<{ muted: boolean; userActivation: boolean; result: string }> };
    let centerReady!: (point: { x: number; y: number }) => void;
    let policyReady!: (observation: PolicyObservation) => void;
    const center = new Promise<{ x: number; y: number }>(resolve => { centerReady = resolve; });
    const policy = new Promise<PolicyObservation>(resolve => { policyReady = resolve; });
    page.on('console', message => {
      const value = message.text();
      if (value.startsWith('preview-policy-center:')) centerReady(JSON.parse(value.slice('preview-policy-center:'.length)));
      if (value.startsWith('preview-policy-settled:')) policyReady(JSON.parse(value.slice('preview-policy-settled:'.length)));
    });
    await page.addInitScript(() => {
      localStorage.setItem('finitude:video-browse-view', 'immersive');
      const attempts: Array<{ muted: boolean; userActivation: boolean; result: string }> = [];
      const nativePlay = HTMLMediaElement.prototype.play;
      HTMLMediaElement.prototype.play = function play(this: HTMLMediaElement) {
        const attempt = this.hasAttribute('data-video-preview') ? {
          muted: this.muted, userActivation: navigator.userActivation.hasBeenActive, result: 'pending'
        } : null;
        if (attempt) attempts.push(attempt);
        const result = nativePlay.call(this);
        // Observe the real promise without changing what the production media layer receives.
        result.then(() => { if (attempt) attempt.result = 'resolved'; }, error => {
          if (attempt) attempt.result = String((error as { name?: string }).name);
        });
        return result;
      };
      let positioned = false;
      let settled = false;
      const observe = () => {
        const card = document.querySelector('[data-video-preview-card]');
        if (!card) return;
        if (!positioned) {
          const bounds = card.getBoundingClientRect();
          if (bounds.width && bounds.height) {
            positioned = true;
            console.debug(`preview-policy-center:${JSON.stringify({ x: bounds.x + bounds.width / 2,
              y: bounds.y + bounds.height / 2 })}`);
          }
        }
        const video = card.querySelector<HTMLVideoElement>('video[data-video-preview][data-ready]');
        const button = card.querySelector('[data-preview-trigger]');
        if (!settled && video && !video.paused && attempts.length
          && button?.getAttribute('aria-pressed') === String(!video.muted)) {
          settled = true;
          console.debug(`preview-policy-settled:${JSON.stringify({ automaticMuted: video.muted,
            userActivation: navigator.userActivation.hasBeenActive, attempts })}`);
        }
      };
      new MutationObserver(observe).observe(document, { childList: true, subtree: true, attributes: true });
    });
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.emulateMedia({ reducedMotion: 'no-preference' });
    await page.goto('/finitude/videos');
    // Normal Playwright mouse moves install drag listeners through a user-gesture evaluation.
    const point = await center;
    const input = await page.context().newCDPSession(page);
    await input.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: point.x, y: point.y,
      button: 'none', buttons: 0, modifiers: 0 });
    const observation = await policy;
    await input.detach();
    await test.info().attach('fresh-page-browser-autoplay', {
      body: JSON.stringify(observation),
      contentType: 'application/json'
    });
    expect(observation.userActivation).toBe(false);
    expect(observation.attempts[0]).toMatchObject({ muted: false, userActivation: false });
    const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
    const preview = card.locator('video[data-video-preview]');
    await expect(preview).toHaveAttribute('data-ready', 'true');
    const { automaticMuted } = observation;
    // Browser autoplay policy varies; the control must describe the actual native sound state.
    await expect(card.getByRole('button', { name: automaticMuted
      ? 'Unmute preview for First Light' : 'Mute preview for First Light', exact: true }))
      .toHaveAttribute('aria-pressed', String(!automaticMuted));
    if (!automaticMuted) await card.getByRole('button', { name: 'Mute preview for First Light', exact: true }).click();
    await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).click();
    await expectAudioSignal(preview);
    await page.keyboard.press('Escape');
    await expect(preview).toHaveCount(0);
    expectNoPreviewActivity(api);
  });
});

test('automatic hover never interrupts an already playing shared source or adds overlapping audio', async ({ api, page }) => {
  await installAudiovisualStream(page);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto(`/finitude/albums/${catalogIds.album}`);
  await page.getByRole('main').getByRole('button', { name: 'Play Night Window', exact: true }).click();
  const player = page.getByRole('region', { name: 'Now playing', exact: true });
  await expect(player.getByRole('button', { name: 'Pause', exact: true })).toBeVisible();
  const main = await page.locator('video:not([data-video-preview])').elementHandle();
  const before = await main!.evaluate(element => ({ time: (element as HTMLVideoElement).currentTime,
    source: (element as HTMLVideoElement).src }));
  await page.getByRole('link', { name: 'Video', exact: true }).click();
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  await card.hover();
  const preview = card.locator('video[data-video-preview]');
  await expect(preview).toHaveAttribute('data-ready', 'true');
  expect(await preview.evaluate(element => (element as HTMLVideoElement).muted)).toBe(true);
  await expect(card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }))
    .toHaveAttribute('aria-pressed', 'false');
  expect(await main!.evaluate(element => ({ connected: element.isConnected,
    paused: (element as HTMLVideoElement).paused, source: (element as HTMLVideoElement).src })))
    .toEqual({ connected: true, paused: false, source: before.source });
  expect(await main!.evaluate(element => (element as HTMLVideoElement).currentTime)).toBeGreaterThan(before.time);
  await expect(player).toContainText('Night Window');
  await page.keyboard.press('Escape');
  await expect(preview).toHaveCount(0);
  await expect(player.getByRole('button', { name: 'Pause', exact: true })).toBeVisible();
  expectNoPreviewActivity(api);
});

