test('unmuting a running original-stream hover keeps its native clock, frames and media lifecycle', async ({ api, page }) => {
  await page.addInitScript(() => localStorage.setItem('finitude:video-preview-muted', 'true'));
  await installAudiovisualStream(page, { motionPreviews: false });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude/videos');
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  const preview = card.locator('video[data-video-preview]');
  await card.hover();
  await expect(preview).toHaveAttribute('data-ready', 'true');
  const initialTime = await preview.evaluate(element => (element as HTMLVideoElement).currentTime);
  await expect.poll(() => preview.evaluate(element => (element as HTMLVideoElement).currentTime))
    .toBeGreaterThan(initialTime + 0.35);
  const continuity = await observeContinuity(preview);
  await expect.poll(async () => (await continuity.read()).frames).toBeGreaterThan(0);
  const before = await continuity.read();
  expect(before.muted).toBe(true);
  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).focus();
  await page.keyboard.press('Enter');
  await expect(card.getByRole('button', { name: 'Mute preview for First Light', exact: true })).toHaveAttribute('aria-pressed', 'true');
  await expect.poll(async () => (await continuity.read()).currentTime).toBeGreaterThan(before.currentTime + 0.15);
  await expect.poll(async () => (await continuity.read()).presentedFrames).toBeGreaterThan(before.presentedFrames);
  const unmuted = await continuity.read();
  expect(unmuted).toMatchObject({ connected: true, muted: false, paused: false, source: before.source });
  expect(unmuted.mediaTime).toBeGreaterThan(before.mediaTime);
  expect(unmuted.counts).toEqual(before.counts);
  await expect(preview).toHaveCount(1);
  await card.getByRole('button', { name: 'Mute preview for First Light', exact: true }).press('Enter');
  await expect(card.getByRole('button', { name: 'Unmute preview for First Light', exact: true })).toHaveAttribute('aria-pressed', 'false');
  expect(await continuity.read()).toMatchObject({ connected: true, muted: true, paused: false,
    source: before.source, counts: before.counts });
  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).press('Enter');
  await expect.poll(async () => (await continuity.read()).muted).toBe(false);
  expect((await continuity.read()).counts).toEqual(before.counts);
  await expectAudioSignal(preview);
  await page.keyboard.press('Escape');
  await expect(preview).toHaveCount(0);
  await expect(page.getByRole('region', { name: 'Now playing', exact: true }).getByText('Nothing playing')).toBeVisible();
  expectNoPreviewActivity(api);
});

test('a pending original-stream audition keeps the dedicated clip moving until decoded handoff', async ({ api, page }) => {
  await page.addInitScript(() => localStorage.setItem('finitude:video-preview-muted', 'true'));
  await installAudiovisualStream(page);
  const original = await gateOriginalStream(page);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto(`/finitude/albums/${catalogIds.album}`);
  await page.getByRole('main').getByRole('button', { name: 'Play Night Window', exact: true }).click();
  const player = page.getByRole('region', { name: 'Now playing', exact: true });
  const controls = player.getByRole('group', { name: 'Playback controls', exact: true });
  await expect(controls.getByRole('button', { name: 'Pause', exact: true })).toBeVisible();
  await controls.getByRole('button', { name: 'Pause', exact: true }).click();
  const main = await page.locator('video:not([data-video-preview])').elementHandle();
  await main!.evaluate(element => {
    (element as HTMLVideoElement).currentTime = 4.5;
    element.dispatchEvent(new Event('timeupdate'));
  });
  await page.getByRole('link', { name: 'Video', exact: true }).click();
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  const clip = card.locator('video[data-video-preview][src*="/motion-preview/"]');
  const stream = card.locator('video[data-video-preview][src*="/mediaTrack/stream/"]');
  await card.hover();
  await expect(clip).toHaveAttribute('data-ready', 'true');
  const continuity = await observeContinuity(clip);
  await expect.poll(async () => (await continuity.read()).frames).toBeGreaterThan(0);
  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).click();
  await expect.poll(original.requested).toBe(true);
  await expect(card.locator('video[data-video-preview]')).toHaveCount(2);
  const candidate = await observeContinuity(stream);
  const pending = await continuity.read();
  await expect.poll(async () => (await continuity.read()).currentTime).toBeGreaterThan(pending.currentTime + 0.35);
  await expect.poll(async () => (await continuity.read()).presentedFrames).toBeGreaterThan(pending.presentedFrames);
  expect(await continuity.read()).toMatchObject({ connected: true, paused: false, muted: true,
    source: pending.source, opacity: 1, counts: pending.counts });
  expect(await stream.evaluate(element => ({ muted: (element as HTMLVideoElement).muted,
    ready: element.getAttribute('data-ready'), opacity: Number(getComputedStyle(element).opacity) })))
    .toEqual({ muted: true, ready: null, opacity: 0 });
  expect(await main!.evaluate(element => ({ connected: element.isConnected,
    paused: (element as HTMLVideoElement).paused, time: (element as HTMLVideoElement).currentTime,
    source: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ connected: true,
    paused: true, time: 4.5, source: `/content/mediaTrack/stream/${catalogIds.secondTrack}` });
  expectNoPreviewActivity(api);

  await original.release();
  await expect(stream).toHaveAttribute('data-ready', 'true');
  await expect(card.locator('video[data-video-preview]')).toHaveCount(1);
  expect((await candidate.read()).audibleFrames).toBeGreaterThan(0);
  expect(await continuity.read()).toMatchObject({ connected: false, paused: true, muted: true });
  expect(await main!.evaluate(element => ({ connected: element.isConnected,
    paused: (element as HTMLVideoElement).paused, time: (element as HTMLVideoElement).currentTime,
    source: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ connected: true,
    paused: true, time: 4.5, source: `/content/mediaTrack/stream/${catalogIds.secondTrack}` });
  await expect(player.getByRole('link', { name: 'Night Window', exact: true }))
    .toHaveAttribute('href', `/finitude/albums/${catalogIds.album}`);
  await expect(controls.getByRole('button', { name: 'Previous MediaTrack', exact: true })).toBeEnabled();
  await expect(controls.getByRole('button', { name: 'Next MediaTrack', exact: true })).toBeDisabled();
  await expectAudioSignal(stream);
  await page.keyboard.press('Escape');
  await expect(card.locator('video[data-video-preview]')).toHaveCount(0);
  expectNoPreviewActivity(api);
});

test('cancelling an audition while its original stream is pending releases both same-card elements', async ({ api, page }) => {
  await page.addInitScript(() => localStorage.setItem('finitude:video-preview-muted', 'true'));
  await installAudiovisualStream(page);
  const original = await gateOriginalStream(page);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude/videos');
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  await card.hover();
  await expect(card.locator('video[data-video-preview]')).toHaveAttribute('data-ready', 'true');
  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).click();
  await expect.poll(original.requested).toBe(true);
  await expect(card.locator('video[data-video-preview]')).toHaveCount(2);
  const elements = await card.locator('video[data-video-preview]').elementHandles();
  await page.keyboard.press('Escape');
  await expect(card.locator('video[data-video-preview]')).toHaveCount(0);
  for (const media of elements) {
    expect(await media.evaluate(element => ({ connected: element.isConnected,
      paused: (element as HTMLVideoElement).paused, muted: (element as HTMLVideoElement).muted,
      source: (element as Element).getAttribute('src') }))).toEqual({ connected: false, paused: true, muted: true, source: null });
  }
  await original.release();
  await page.evaluate(() => new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));
  await expect(page.locator('video[data-video-preview]')).toHaveCount(0);
  await expect(page.getByRole('region', { name: 'Now playing', exact: true }).getByText('Nothing playing')).toBeVisible();
  expectNoPreviewActivity(api);
});

test('configured muted hover stays silent while keyboard auditions retain audio, their stream and one-preview ownership', async ({ api, page }) => {
  await page.addInitScript(() => localStorage.setItem('finitude:video-preview-muted', 'true'));
  await installAudiovisualStream(page, { twoCards: true });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude/videos');
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  const preview = card.locator('video[data-video-preview]');
  await card.hover();
  await expect(preview).toHaveAttribute('data-ready', 'true');
  expect(await preview.evaluate(element => ({ muted: (element as HTMLVideoElement).muted,
    path: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ muted: true,
    path: `/content/mediaTrack/motion-preview/${catalogIds.firstTrack}` });

  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).focus();
  await page.keyboard.press('Enter');
  await expect(card.locator('video[data-video-preview][src*="/mediaTrack/stream/"]')).toHaveAttribute('data-ready', 'true');
  await expect(preview).toHaveCount(1);
  await expect(card.getByRole('button', { name: 'Mute preview for First Light', exact: true })).toHaveAttribute('aria-pressed', 'true');
  const stream = await preview.elementHandle();
  const streamPath = `/content/mediaTrack/stream/${catalogIds.firstTrack}`;
  expect(await stream!.evaluate(element => ({ muted: (element as HTMLVideoElement).muted,
    path: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ muted: false, path: streamPath });
  await page.keyboard.press('Enter');
  await expect(card.getByRole('button', { name: 'Unmute preview for First Light', exact: true })).toHaveAttribute('aria-pressed', 'false');
  expect(await stream!.evaluate(element => ({ connected: element.isConnected,
    muted: (element as HTMLVideoElement).muted, paused: (element as HTMLVideoElement).paused,
    path: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ connected: true,
    muted: true, paused: false, path: streamPath });
  await expect(page.locator('video[data-video-preview]')).toHaveCount(1);

  const otherCard = page.locator(`[data-video-preview-card="${otherPreview.id}"]`);
  // A programmatic click keeps pointer and focus in the first card, isolating global preview ownership.
  await otherCard.getByRole('button', { name: 'Unmute preview for Another Light', exact: true }).dispatchEvent('click');
  await expect(otherCard.locator('video[data-video-preview]')).toHaveAttribute('data-ready', 'true');
  await expect(page.locator('video[data-video-preview]')).toHaveCount(1);
  expect(await stream!.evaluate(element => ({ connected: element.isConnected,
    muted: (element as HTMLVideoElement).muted, paused: (element as HTMLVideoElement).paused })))
    .toEqual({ connected: false, muted: true, paused: true });
  await expectAudioSignal(otherCard.locator('video[data-video-preview]'));
  await page.keyboard.press('Escape');
  await expect(page.locator('video[data-video-preview]')).toHaveCount(0);
  await expect(page.getByRole('region', { name: 'Now playing', exact: true }).getByText('Nothing playing')).toBeVisible();
  expectNoPreviewActivity(api);
});

test('audible preview pauses the shared source without changing its elapsed time or album queue', async ({ api, page }) => {
  await installAudiovisualStream(page);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto(`/finitude/albums/${catalogIds.album}`);
  await page.getByRole('main').getByRole('button', { name: 'Play Night Window', exact: true }).click();
  const player = page.getByRole('region', { name: 'Now playing', exact: true });
  const controls = player.getByRole('group', { name: 'Playback controls', exact: true });
  await expect(controls.getByRole('button', { name: 'Pause', exact: true })).toBeVisible();
  const main = await page.locator('video:not([data-video-preview])').elementHandle();
  await main!.evaluate(element => {
    (element as HTMLVideoElement).currentTime = 4.5;
    element.dispatchEvent(new Event('timeupdate'));
  });
  await page.getByRole('link', { name: 'Video', exact: true }).click();
  await page.getByRole('button', { name: 'Immersive preview', exact: true }).click();
  const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).click();
  const preview = card.locator('video[data-video-preview]');
  await expect(preview).toHaveAttribute('data-ready', 'true');
  await expect(controls.getByRole('button', { name: 'Play', exact: true })).toBeVisible();
  const pausedTime = await main!.evaluate(element => (element as HTMLVideoElement).currentTime);
  expect(pausedTime).toBeGreaterThanOrEqual(4.5);
  await card.getByRole('button', { name: 'Mute preview for First Light', exact: true }).click();
  await expect(preview).toHaveCount(1);
  expect(await preview.evaluate(element => (element as HTMLVideoElement).muted)).toBe(true);
  expect(await main!.evaluate(element => ({ connected: element.isConnected,
    paused: (element as HTMLVideoElement).paused, time: (element as HTMLVideoElement).currentTime,
    path: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ connected: true,
    paused: true, time: pausedTime, path: `/content/mediaTrack/stream/${catalogIds.secondTrack}` });
  await expect(controls.getByRole('button', { name: 'Previous MediaTrack', exact: true })).toBeEnabled();
  await expect(controls.getByRole('button', { name: 'Next MediaTrack', exact: true })).toBeDisabled();

  await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).click();
  await expect(card.getByRole('button', { name: 'Mute preview for First Light', exact: true })).toBeVisible();
  // Dispatch the real transport action without pointerleave/focusout masking the global stop contract.
  await controls.getByRole('button', { name: 'Play', exact: true }).dispatchEvent('click');
  await expect(page.locator('video[data-video-preview]')).toHaveCount(0);
  await expect(controls.getByRole('button', { name: 'Pause', exact: true })).toBeVisible();
  expect(await main!.evaluate(element => ({ connected: element.isConnected,
    paused: (element as HTMLVideoElement).paused,
    path: new URL((element as HTMLVideoElement).src).pathname }))).toEqual({ connected: true,
    paused: false, path: `/content/mediaTrack/stream/${catalogIds.secondTrack}` });
  expect(await main!.evaluate(element => (element as HTMLVideoElement).currentTime)).toBeGreaterThanOrEqual(pausedTime);
  // Previous first rewinds a track past three seconds; the next press reveals the preserved queue.
  await controls.getByRole('button', { name: 'Previous MediaTrack', exact: true }).click();
  await expect.poll(() => main!.evaluate(element => (element as HTMLVideoElement).currentTime)).toBeLessThan(1);
  await controls.getByRole('button', { name: 'Previous MediaTrack', exact: true }).click();
  await expect(player).toContainText('First Light');
  expectNoPreviewActivity(api);
});

test.describe('touch audio preview', () => {
  test.use({ hasTouch: true, isMobile: true, viewport: { width: 390, height: 844 } });

  test('a tap unmutes real audio and a second tap mutes the same continuing stream', async ({ api, page }) => {
    await installAudiovisualStream(page);
    await page.emulateMedia({ reducedMotion: 'reduce' });
    await page.goto('/finitude/videos');
    await page.getByRole('button', { name: 'Immersive preview', exact: true }).tap();
    const card = page.locator(`[data-video-preview-card="${catalogIds.firstTrack}"]`);
    await expect(card.locator('video[data-video-preview]')).toHaveCount(0);
    await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).tap();
    const preview = card.locator('video[data-video-preview]');
    await expect(preview).toHaveAttribute('data-ready', 'true');
    const media = await preview.elementHandle();
    const source = await preview.getAttribute('src');
    expect(new URL(source!, page.url()).pathname).toBe(`/content/mediaTrack/stream/${catalogIds.firstTrack}`);
    expect(await preview.evaluate(element => (element as HTMLVideoElement).muted)).toBe(false);
    await card.getByRole('button', { name: 'Mute preview for First Light', exact: true }).tap();
    expect(await media!.evaluate(element => ({ connected: element.isConnected,
      muted: (element as HTMLVideoElement).muted, paused: (element as HTMLVideoElement).paused,
      source: element.getAttribute('src') }))).toEqual({ connected: true, muted: true, paused: false, source });
    await card.getByRole('button', { name: 'Unmute preview for First Light', exact: true }).tap();
    await expectAudioSignal(preview);
    await page.keyboard.press('Escape');
    await expect(preview).toHaveCount(0);
    await expect(page.getByRole('region', { name: 'Now playing', exact: true }).getByText('Nothing playing')).toBeVisible();
    expectNoPreviewActivity(api);
  });
});
